INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('lord-kreelo', 'Lord Kreelo', 'Kreelo Tok-Mal (true name)', 'Dimensional Arms Dealer, owner of Megaverse Armaments', 'rifts', 'Chaos Demon of unknown origin, tied to neither Hades nor Dyval (as printed)', '10th level Soulmancer and 6th level Necromancer (as printed)', 10, 'Diabolic', 'Effectively immortal', 'Mutable; 15 feet, 6 inches (4.7 m) in his natural form', 'Four tons in his natural form', '{"IQ":28,"ME":21,"MA":24,"PS":28,"PP":20,"PE":26,"PB":8,"Spd":20}', 1050, 1900, 2950, 1300, 240, 14, 15, '{"attacks":10,"initiative":4,"strike":5,"parry":8,"dodge":6,"pull":4,"roll":4}', 'Spd 20 running, 120 flying (80 mph/128 km) and 60 swimming (40 mph/64 km). Hit Points 1,050, S.D.C. 1,900 and Natural A.R. 14 are the block''s S.D.C.-setting figures. Also +4 on Perception Rolls, +8 to save vs Horror Factor, +9 vs magic, +5 vs psionics and +2 on all other saves. Supernatural P.S. 28. Horror Factor 15 in his natural form, or that of whatever being he is impersonating. W.P. Blunt at 10th level.', '[{"name":"Appraise Goods","pct":89},{"name":"Barter","pct":98},{"name":"Brewing","pct":84},{"name":"Computer Operation","pct":98},{"name":"Gemology","pct":84},{"name":"Horsemanship: Exotic Animals","pct":89},{"name":"Intelligence","pct":82},{"name":"Jury-Rig","pct":84},{"name":"Land Navigation","pct":86},{"name":"Literacy: American","pct":89},{"name":"Literacy: Dragonese/Elven","pct":89},{"name":"Literacy: Splugorth","pct":89},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Faeries & Creatures of Magic","pct":98},{"name":"Lore: Magic","pct":98},{"name":"Lore: Psychics & Psionics","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Military Fortification","pct":89},{"name":"Public Speaking","pct":89},{"name":"Radio: Basic","pct":98},{"name":"Research","pct":98},{"name":"Salvage","pct":98},{"name":"Streetwise","pct":90},{"name":"Wilderness Survival","pct":89}]', 'Skills of note only. Brewing is printed 84%/89% and Horsemanship: Exotic Animals 89%/79%; the first figure is kept. Printed as Jury Rig, Lore: Demons and Monsters and Literacy: Dragonese; those carry their catalog names. Literacy is printed once at 89% for American, Dragonese and Splugorth; American and Splugorth have no catalog row. Also W.P. Blunt at 10th level, printed without a percentage.', 'Supernatural Strength and Endurance. Nightvision 500 feet (152.4 m); he sees in total darkness, in four directions at once, and sees the invisible. Resists magic: beyond his save bonus, a failed save costs him only half the damage and duration. Speaks and reads every language by magic at 80%. Dimensional teleport 73%. Heals 3D6 M.D. each melee round by Bio-Regeneration. Can take the shape of any kind of demon (of Hades, Dyval, Russia, the Daemonix and others), though never of one particular individual. Vulnerabilities: fire and cold do him double damage, magic fire and ice and M.D. plasma included; ordinary M.D. weapons do full damage and silver does its damage as M.D. Disciplined minds (Cyber-Knights, Ley Line Walkers, Mind Melters and the like) are +1 to save against him and chaotic ones (Juicers, Crazies) -1, at the G.M.''s judgment.', 'Every Soulmancy spell and ritual and every Necromancy spell, plus all level one invocations and Agony (20), Animate and Control Dead (20), Anti-Magic Cloud (140), Armor of Ithan (10), Blind (6), Call Lightning (15), Chameleon (6), Charismatic Aura (10), Cleanse (6), Domination (10), Electric Arc (8), Energy Sphere (120), Escape (8), Fear (5), Fool''s Gold (20), Firequake (160), Havoc (70), Horrific Illusion (10), Invisibility: Simple (6), Mute (55), Mystic Portal (60), Negate Magic (30), Orb of Cold (6), Steel Rain (360), Teleport: Superior (600) and Wind Rush (20). P.P.E. 1,300.', 'All Physical powers plus Astral Projection (8), Bio-Manipulation (the evil eye) (10), Hypnotic Suggestion (6), Mind Block Auto-Defense (special), Mind Bolt (varies), Object Read (Psychometry) (6), Presence Sense (4), See Aura (6), Telekinesis (Super) (10+) and Telepathy (4). I.S.P. 240; a Master Psychic.', NULL, NULL, 'Seldom uses any, for all his hoard: fighting is for his minions, and in a pinch he defends himself with magic and psionics. His company''s wares are held in the catalog as their own rows: the BEW Wrist Blaster, BEW Shoulder Blaster, BEW Blood Rifle, BEW Blood Cannon, Flesh Armor and Bone Armor (gear), and the BEW Chaos Trooper Armor, BEW Meat Grinder Tank, BEW Carnage Tank and BEW Walking Death (vehicles).', 'Untold trillions in Phase World Trade Credits besides Universal Credits, a great many Modeus coins, other gold coins and gems, magic scrolls and books, and magic weapons and artifacts gathered across the Megaverse: a hoard to shame an ancient dragon.', 'Greedy, manipulative and condescending, with a used-car salesman''s charm. A born instigator who knows the words and pressures that start quarrels and betrayals. He lives on chaos the way others live on P.P.E. or emotion, so he sells to both sides of the Minion War, tips the balance toward whichever is losing, and laughs off any discovery of his double-dealing with a discount.', 'Outcast demons and Creatures of Chaos, several in his employ (the G.M. may draw on Rifts Chaos Earth Sourcebook One: Creatures of Chaos), and a fondness for Crazies and Juicers, whose lives he lengthens with Soulmancy as both reward and experiment. Hundreds of minions, spies, mercenaries and cutthroats, not all of them demons; Hades demons may guard one of his secret facilities and Dyvalians another.', 'The Soldiers of Light above all: he fears them and has posted several bounties on them. The Splugorth think him an upstart. NEMA drove him out of the Chicago ruins when the Rifts first opened, and heroes of the Palladium world beat him so badly long ago that he will not return there.', 'A demon lord of some chaotic breed, answering to neither Hades nor Dyval, who grows rich arming both sides of the Minion War through his company, Megaverse Armaments. Legend says an Alien Intelligence brought him into being by speaking his name at the Gateway to the Megaverse; his own search for his origins keeps pointing to the Palladium world. Arriving on Earth with the first wave of the Rifts, he was chased from Chicago by NEMA into a war between demon and Deevil armies that he worked out had been flung back in time, and spent centuries stockpiling weapons before the war broke out. His natural form is a round body on three legs with two mouths, six arms, four large and a dozen small tentacles and four eyestalks. The company works from a pocket dimension of caves, perhaps in the Elemental Plane of Earth, centred on a nexus, where a dozen or so Soulmancy factories burn through slaves held in an internment camp; he raids for slaves or buys them from the Splugorth, and steals tanks, robots and power armor, even from Naruni Enterprises and the Splugorth, to rework for demonic buyers. He leads no army: his company and its hirelings are his force.', 'Rifts World Book 35: Megaverse in Flames p.111-113'),
('overlord-shard', 'Overlord Shard', 'So''Jan Shardric (true name); the Tower Grim within him is also known as Sulathas Grimkeeper', 'Deevil Overlord, Sahtalus'' commander on Rifts Earth, leader of the Dimension Stormers', 'rifts', 'Deevil of Dyval, a Lesser Deevil raised to Deevil Lord, sharing his body with a splinter of the Tower Grim''s life essence', '8th Level (as printed)', 8, 'Diabolic', 'Effectively immortal', 'Mutable: Shard prefers 10 feet (3 m), Grim 18 feet (5.5 m); as large as 24 feet (7.3 m)', 'Up to 15 tons at his largest', '{"IQ":20,"ME":18,"MA":26,"PS":32,"PP":24,"PE":22,"PB":18,"Spd":45}', 372, 500, 872, 522, 180, 14, 15, '{"attacks":9,"initiative":4,"strike":7,"parry":7,"dodge":7,"pull":4,"roll":5}', 'The combat figures are Grim''s, the dominant personality: nine attacks, also +2 on Perception Rolls, +6 to save vs Horror Factor, +6 vs magic, +8 vs psionics (a Master Psionic) and +2 on Spell Strength. When Shard is in control: six attacks, +2 on initiative, +5 to strike, parry and dodge, +2 to pull punch and to roll with fall/impact, +4 to save vs Horror Factor, +8 vs magic, +4 vs psionics and +2 on Spell Strength. The attributes are Shard''s; Grim''s mental ones are I.Q. 28, M.E. 27 and M.A. 22, and P.S. is 52 (Supernatural) under Grim. M.D.C. 872, plus 1,000 in Grim''s combat persona. Hit Points 372, S.D.C. 500 and A.R. 14 are the block''s S.D.C.-setting figures; the combat persona adds 500 S.D.C. and raises A.R. and Horror Factor to 16. W.P. Archery, Energy Rifle, Knives and Swords.', '[{"name":"Astronomy & Navigation","pct":95},{"name":"Camouflage","pct":75},{"name":"Detect Ambush","pct":85},{"name":"Detect Concealment","pct":80},{"name":"Horsemanship: Exotic Animals","pct":85},{"name":"Intelligence","pct":80},{"name":"Interrogation","pct":85},{"name":"Literacy: American","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Lore: Demons & Monsters","pct":90},{"name":"Lore: Dimensions","pct":80},{"name":"Lore: Faeries & Creatures of Magic","pct":85},{"name":"Lore: Magic","pct":85},{"name":"Land Navigation","pct":84},{"name":"Mathematics: Basic","pct":98},{"name":"Military Etiquette","pct":90},{"name":"Military Fortification","pct":85},{"name":"Hovercycles, Skycycles & Rocket Bikes","pct":98},{"name":"Public Speaking","pct":85},{"name":"Recognize Weapon Quality","pct":80},{"name":"Swimming","pct":98},{"name":"Wilderness Survival","pct":80}]', 'Skills of note only. Horsemanship: Exotic is printed 85%/75% and the first figure is kept. Printed as Horsemanship: Exotic, Literacy: Dragonese and Pilot: Hovercycles; those carry their catalog names. Literacy is printed once at 98% for American, Demongogian, Dragonese and Euro; American and Demongogian have no catalog row. Running is printed without a percentage, as are W.P. Archery, Energy Rifle, Knives and Swords.', 'Nightvision 1,000 feet (305 m); sees the invisible. Resists heat and cold: half damage from magic heat, M.D. plasma and magic cold. Bio-Regenerates 4D6 each melee round (the unit is not printed). Understands and speaks every language by magic. Turns invisible at will for as long as he likes, has the Metamorphosis: Human every Deevil and Devilkin shares, and can change size and become a hulking combat brute at will. While Grim is in control he also has a Shifter''s powers: Dimension Sense 80%, Dimensional Travel 88%, Dimensional Teleport: Home (to Grim Mortis and the Tower Grim) 96% and Sense Rifts 90%. Vulnerabilities: S.D.C. weapons of wood or silver do their damage as M.D.; hot-tempered, given to outbursts and to bad judgment mid-fight.', 'While Shard is in control, only the spells common to Deevils. Only while Grim is dominant: Agony (20), Annihilate (600), Armor of Ithan (10), Ballistic Fire (25), Blinding Flash (1), Call Lightning (15), Circle of Flame (10), Circle of Travel (600), Climb (3), Cloud of Smoke (2), Deflect (10), Desiccate the Supernatural (50), Dimensional Portal (1000), Dimensional Teleport (800), Electric Arc (8), Energy Bolt (5), Escape (8), Fire Ball (10), Fire Blast (8), Fire Blossom (20), Fire Bolt (7), Firequake (160), Havoc (70), Lightning Arc (30), Negate Poison/Toxin (5), Orb of Cold (6), Power Bolt (20), Rift Teleportation (200), Rift to Limbo (160), Sense Magic (4), Shockwave (45), Spinning Blades (20), Steel Rain (360), Sub-Particle Acceleration (20), Teleport: Lesser (15), Teleport: Superior (600) and Turn Dead (6). P.P.E. 522.', 'Only while Grim is dominant: Read Dimensional Portal (6), Sense Time (2), Telekinesis (Super) (10+), Telekinetic Acceleration Attack (10 or 20), Telekinetic Leap (8), Telekinetic Lift (8) and Telekinetic Push (4). I.S.P. 180; a Master Psionic.', NULL, NULL, 'Dragon Hide armor of 400 M.D.C., enchanted to weigh nothing, to resize to its wearer (so it changes with him) and to regenerate 1D6 M.D.C. a minute; it rebuilds itself wholly while at least 15% (60 M.D.C.) remains and is destroyed below that. A dragon-bone claymore whose hilt is a dragon''s head, doing 4D6 S.D.C. to mortals and 1D6x10 M.D. to dragons, serpents, all reptiles (Gargoyles included) and good supernatural beings. A Maggot''s Eye Amulet and a Hell Rifle, held in the catalog as the gear rows Maggot Eye Amulet and Hell Rifle.', 'Brought to Earth as bargaining stock: the equivalent of 10 million credits in precious metals, 30 million in gems and 10 million in magic items.', 'Two personalities share the body, so he seems mad. Grim, in charge all but about 40% of the time, is articulate, clever and aggressive, a capable general who leads from the front, and also a sadistic, spoiled child thrilled by each new taste of war and killing. Shard is a crude bully and backstabber, a poor strategist and something of a coward, who takes advice from his officers, prefers tricks to fighting and countermands Grim''s riskier orders. They argue aloud in two different voices, and nobody can predict what he will do next.', 'Most of his troops stay loyal despite his unpredictability, out of respect for his power and mind; they would likely scatter if he fell and no strong leader stepped in. Looking for allies against Grim, Shard has unknowingly fallen in with spies working for Mephisto.', 'The Demons of Hades and various Earth factions. Overlord Stheno, whose repeated offers to join forces he has refused and whom he suspects of a few attempts on his life, and Overlord Sindel, whom he nearly fought at their first meeting in Grim Mortis until Lady Hel intervened. Overlord Necroskull envies him and thinks him a mad fool. Each personality is the other''s worst enemy, and Shard expects that destroying the Tower Grim will set him against Sahtalus himself.', 'Sahtalus'' chosen commander for the conquest of Rifts Earth: a handsome crimson-skinned Deevil with a goat''s shaggy lower body, golden hooves, upright golden horns and black tattoos across his torso. No Deevil knows where he came from, and his troops mock him as Broken Shard behind his back. The truth is that the sentient Tower Grim, Sahtalus'' own citadel and perhaps an Alien Intelligence, slipped a fragment of its essence into him during the ritual that raised a Lesser Deevil to Overlord, and the two now fight for one body. His erratic conduct in battle, retreating while winning, vanishing by Dimensional Teleport or seeking out the enemy commander alone, has still won far more than it lost. Shard believes that destroying the tower and its Soul Chamber will rid him of Grim, hides the secret from Sahtalus, and is ready to fight his master for it. He leads the Dimension Stormer Army, organised along naval lines in Hell Galleons, with a pair each of Hell Schooners and Hell Battle Barges, off the eastern and southern coasts of the United States, with small scouting forces spread through the Americas; he commands the Deevils in Ciudad de Diablo and holds as many again in reserve at Grim Mortis until his Hell Pit is finished. The book adds an optional table for which personality is in charge when he is met: Grim with full bonuses, the two distracted by an argument, or Shard, who is quick to flee.', 'Rifts World Book 35: Megaverse in Flames p.152-156'),
('overlord-necroskull', 'Overlord Necroskull', 'Kall Rham (true name)', 'Deevil Overlord, leader of the Flaming Skulls', 'rifts', 'Nexus Deevil, mutated into a giant floating skull fused with a Fire Elemental''s power', '10th level Deevil Scout and dimensional traveler (as printed)', 10, 'Miscreant', 'Effectively Immortal', 'A giant head 20 feet (6.1 m) tall', '10 tons', '{"IQ":27,"ME":26,"MA":25,"PS":20,"PP":18,"PE":21,"PB":2,"Spd":44}', 1100, 660, 2360, 520, 360, 16, 16, '{"attacks":8,"initiative":2,"strike":4,"dodge":2,"pull":4,"roll":4}', 'The +4 to strike is printed for the head butt or bite. Saves: +6 vs Horror Factor, +5 vs magic, +6 vs psionics; a Master Psionic. Hit Points 1,100, S.D.C. 660 and A.R. 16 are the block''s S.D.C.-setting figures. Spd 44 hovering and flying (30 mph/48 km), no higher than 500 feet (152.4 m); hovering is his only way of moving. W.P. Blunt and Energy Pistol.', '[{"name":"Computer Operation","pct":90},{"name":"Detect Ambush","pct":98},{"name":"Detect Concealment","pct":93},{"name":"Intelligence","pct":96},{"name":"Land Navigation","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Literacy: Dwarven","pct":98},{"name":"Literacy: Greek","pct":98},{"name":"Literacy: Splugorth","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Lore: Demons & Monsters","pct":83},{"name":"Lore: Magic","pct":83},{"name":"Lore: Psychics & Psionics","pct":83},{"name":"Mathematics: Basic","pct":98},{"name":"Military Etiquette","pct":98},{"name":"Prowl","pct":98},{"name":"Radio: Basic","pct":98},{"name":"Surveillance","pct":98},{"name":"Tailing","pct":98},{"name":"Wilderness Survival","pct":98}]', 'Skills of note only. Literacy is printed once at 98% for seven languages; Dragonese and Euro carry catalog names and the other five have no catalog row. Printed as Lore: Demons and Monsters, Lore: Psychics and Surveillance Systems/Tailing; those carry their catalog names, the last split into Surveillance and Tailing at the one printed figure. W.P. Blunt and Energy Pistol, printed without a percentage.', 'He has lost most of a Nexus Deevil''s abilities and bonuses but keeps its Powers of Dimensional Travel (Dimension Book 11: Dyval). Hovers as his natural state and flies; Nightvision 2,000 feet (610 m); sees the invisible; turns invisible at will for any length of time; heals 4D6 a melee by Bio-Regeneration (the unit is not printed); dimensional teleport 73%; understands all languages by magic. Elemental powers from his fusion with a Fire Elemental: a Fire Aura of 200 extra M.D.C., six times a day, that burns anyone touching it for 2D6 M.D. and readily sets combustibles alight, immune to heat and fire but taking double damage from cold and water; plasma bolts from the eyes, 2D6 M.D. each, unlimited, raised with P.P.E. as far as 1D6x10 M.D., range 2,000 feet (610 m); a fire breath once a melee, 5D6 M.D. at 40 feet (12.2 m); and he can vomit up 1D6+2 Flame Fiends (as the Fire Warlock spell) lasting as long as 10 hours, or instead call four Minor Fire Elementals (5 hours) or a single Major one (an hour), after which a day must pass before he calls more, and never sends them to fight to the death. Vulnerabilities: cold does double damage and Millennium Tree weapons triple; magic and psionics do normal damage.', 'All Fire Elemental spells, from his bond with a Fire Elemental. P.P.E. 520, which also powers up his eye bolts.', 'All Sensitive and Physical powers plus Bio-Manipulation (the evil eye) (10), Hypnotic Suggestion (6), Pyrokinesis (varies), Telekinesis (Super) (10+) and Telekinetic Acceleration Attack (10 or 20). I.S.P. 360; a Master Psionic.', NULL, NULL, 'Uses none himself, but has taken a small hoard of magic weapons and armor over the years, at least one Rune sword from a fallen demon among them, most of it probably hidden in his secret bases.', 'At least five hidden lairs, each holding 1D4x10 million in magic items, precious metals, gems and other treasure.', 'Merciless to the core, ruling through fear and brutality so that his minions dare not question him. Obsessed with destroying the Demons of Hades, he captures them to torture and maim, and the obsession could lead him to march his troops into Hades itself; only the stakes on Rifts Earth hold him back. He hates vampires nearly as much.', 'Of the Deevil Lords only Nickodeamis has faith in him; having once served Old Nick, he answers to him and acts as his eyes and ears on Rifts Earth. His own troops follow him out of fear.', 'The Demons of Hades: he has slain many notable Demon Princes, and demon assassins have tried for him repeatedly without success. He sees humans as cattle and pawns to enslave, and envies Overlord Shard, whom he holds a madman and a fool.', 'Once Kall Rham, a Nexus Deevil scout who worked alone reconnoitring other worlds. While he led a caravan carrying Lord Diabolus'' mutagenic compound and captured Elementals, demons ambushed it, threw him into the compound, ate his body and flung his severed head into a ravine flooded with the mutagen beside a caged Fire Elemental. The compound kept him from discorporating, and his regeneration poured into the head, which grew huge and merged with the Elemental''s power: a floating Deevil skull with fiery eyes, scraps of hair and curling horns. He hunted down and devoured his captors, slew the Greater Deevil who called him an abomination, and was hailed master by its troops. Campaigns of conquest earned him the rank of Overlord and the charge of driving the demons from Rifts Earth. His army, the Flaming Skulls, flies a black banner bearing a flaming red and yellow skull and leans on Shifters and Soulmancers who summon Elementals and Shadow Beasts ahead of the main assault. He means to aim it first at Calgary and Hell Lord Doom, then at the next demon horde and perhaps the Vampire Kingdoms, while elite troops wait disguised in the Splynn Dimensional Market and the nearby mountains to seize a stone pyramid once the demons strike Atlantis.', 'Rifts World Book 35: Megaverse in Flames p.156-158');
